def transform(grid):
    # Find distinct 2x2 color-2 squares. Recolor squares in groups of at
    # least two that touch by an edge; isolated squares remain color 2.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    blocks = set()
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[y][x] == 2 for y in (r, r + 1) for x in (c, c + 1)):
                blocks.add((r, c))
    seen = set()
    for start in blocks:
        if start in seen:
            continue
        stack = [start]
        seen.add(start)
        component = []
        while stack:
            r, c = stack.pop()
            component.append((r, c))
            for nxt in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if nxt in blocks and nxt not in seen:
                    seen.add(nxt)
                    stack.append(nxt)
        if len(component) >= 2:
            for r, c in component:
                for y in (r, r + 1):
                    for x in (c, c + 1):
                        out[y][x] = 8
    return out
